import { createHash, createHmac } from "node:crypto";
import type { Offer } from "../types";
import type { RetailerProvider } from "./provider";

const HOST = "webservices.amazon.com";
const REGION = "us-east-1";
const SERVICE = "ProductAdvertisingAPI";
const PATH = "/paapi5/searchitems";
const TARGET = "com.amazon.paapi5.v1.ProductAdvertisingAPIv1.SearchItems";

function sha256(value: string) {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function hmac(key: Buffer | string, value: string) {
  return createHmac("sha256", key).update(value, "utf8").digest();
}

function signHeaders(body: string, accessKey: string, secretKey: string) {
  const amzDate = new Date().toISOString().replace(/[:-]|\.\d{3}/g, "");
  const dateStamp = amzDate.slice(0, 8);
  const headers: Record<string, string> = {
    "content-encoding": "amz-1.0",
    "content-type": "application/json; charset=utf-8",
    host: HOST,
    "x-amz-date": amzDate,
    "x-amz-target": TARGET,
  };
  const signedHeaders = Object.keys(headers).sort().join(";");
  const canonicalHeaders = Object.keys(headers)
    .sort()
    .map((k) => `${k}:${headers[k]}\n`)
    .join("");
  const canonicalRequest = ["POST", PATH, "", canonicalHeaders, signedHeaders, sha256(body)].join("\n");
  const scope = `${dateStamp}/${REGION}/${SERVICE}/aws4_request`;
  const stringToSign = ["AWS4-HMAC-SHA256", amzDate, scope, sha256(canonicalRequest)].join("\n");
  const signingKey = hmac(hmac(hmac(hmac(`AWS4${secretKey}`, dateStamp), REGION), SERVICE), "aws4_request");
  const signature = createHmac("sha256", signingKey).update(stringToSign, "utf8").digest("hex");
  headers.authorization = `AWS4-HMAC-SHA256 Credential=${accessKey}/${scope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;
  return headers;
}

type PaapiItem = {
  ASIN: string;
  DetailPageURL: string;
  ItemInfo?: { Title?: { DisplayValue?: string } };
  Images?: { Primary?: { Medium?: { URL?: string } } };
  Offers?: { Listings?: Array<{ Price?: { Amount?: number }; Availability?: { Type?: string } }> };
  CustomerReviews?: { StarRating?: { Value?: number } };
};

export const amazonProvider: RetailerProvider = {
  id: "amazon",
  isConfigured() {
    return Boolean(
      process.env.AMAZON_PAAPI_ACCESS_KEY && process.env.AMAZON_PAAPI_SECRET && process.env.AMAZON_PARTNER_TAG,
    );
  },
  async search(query, filters) {
    const body = JSON.stringify({
      Keywords: query,
      SearchIndex: "Baby",
      ItemCount: 3,
      PartnerTag: process.env.AMAZON_PARTNER_TAG,
      PartnerType: "Associates",
      Marketplace: "www.amazon.com",
      ...(filters.maxPrice ? { MaxPrice: Math.round(filters.maxPrice * 100) } : {}),
      Resources: [
        "ItemInfo.Title",
        "Images.Primary.Medium",
        "Offers.Listings.Price",
        "Offers.Listings.Availability.Type",
        "CustomerReviews.StarRating",
      ],
    });
    const response = await fetch(`https://${HOST}${PATH}`, {
      method: "POST",
      headers: signHeaders(body, process.env.AMAZON_PAAPI_ACCESS_KEY!, process.env.AMAZON_PAAPI_SECRET!),
      body,
    });
    if (!response.ok) throw new Error(`Amazon search failed (${response.status})`);
    const data = (await response.json()) as { SearchResult?: { Items?: PaapiItem[] } };
    return (data.SearchResult?.Items ?? []).map(
      (item): Offer => ({
        retailer: "amazon",
        externalId: item.ASIN,
        title: item.ItemInfo?.Title?.DisplayValue ?? query,
        price: item.Offers?.Listings?.[0]?.Price?.Amount ?? null,
        imageUrl: item.Images?.Primary?.Medium?.URL ?? null,
        url: item.DetailPageURL,
        rating: item.CustomerReviews?.StarRating?.Value ?? null,
        inStock: item.Offers?.Listings?.[0]?.Availability?.Type !== "OutOfStock",
      }),
    );
  },
};

import { createSign } from "node:crypto";
import type { Offer } from "../types";
import type { RetailerProvider } from "./provider";

type WalmartItem = {
  itemId: number;
  name: string;
  salePrice?: number;
  mediumImage?: string;
  thumbnailImage?: string;
  productTrackingUrl?: string;
  productUrl?: string;
  customerRating?: string;
  stock?: string;
};

function authHeaders() {
  const consumerId = process.env.WALMART_CONSUMER_ID!;
  const keyVersion = process.env.WALMART_KEY_VERSION ?? "1";
  const privateKey = process.env.WALMART_PRIVATE_KEY!.replace(/\\n/g, "\n");
  const timestamp = Date.now().toString();
  const signer = createSign("RSA-SHA256");
  signer.update(`${consumerId}\n${timestamp}\n${keyVersion}\n`);
  return {
    "WM_CONSUMER.ID": consumerId,
    "WM_CONSUMER.INTIMESTAMP": timestamp,
    "WM_SEC.KEY_VERSION": keyVersion,
    "WM_SEC.AUTH_SIGNATURE": signer.sign(privateKey, "base64"),
  };
}

export const walmartProvider: RetailerProvider = {
  id: "walmart",
  isConfigured() {
    return Boolean(
      process.env.WALMART_CONSUMER_ID && process.env.WALMART_PRIVATE_KEY && process.env.WALMART_PUBLISHER_ID,
    );
  },
  async search(query, filters) {
    const params = new URLSearchParams({
      query,
      numItems: "3",
      publisherId: process.env.WALMART_PUBLISHER_ID!,
    });
    const response = await fetch(
      `https://developer.api.walmart.com/api-proxy/service/affil/product/v2/search?${params}`,
      { headers: authHeaders() },
    );
    if (!response.ok) throw new Error(`Walmart search failed (${response.status})`);
    const data = (await response.json()) as { items?: WalmartItem[] };
    return (data.items ?? [])
      .filter((item) => !filters.maxPrice || (item.salePrice ?? 0) <= filters.maxPrice)
      .map(
        (item): Offer => ({
          retailer: "walmart",
          externalId: String(item.itemId),
          title: item.name,
          price: item.salePrice ?? null,
          imageUrl: item.mediumImage ?? item.thumbnailImage ?? null,
          url: item.productTrackingUrl ?? item.productUrl ?? `https://www.walmart.com/ip/${item.itemId}`,
          rating: item.customerRating ? Number(item.customerRating) : null,
          inStock: item.stock !== "Not available",
        }),
      );
  },
};

